"""Own-render publication and private VR comparison, with explicit limits."""
from pathlib import Path
from PIL import Image
import json,html
R=Path(__file__).resolve().parents[1];W=R/'work/right-engine-r01';P=R/'public/review';D=P/'right-engine-r01';D.mkdir(parents=True,exist_ok=True)
read=lambda p:json.loads(p.read_text())
e=read(R/'public/assets/mechanics/right-vr-r01/evidence.json');a=read(R/'public/assets/mechanics/right-vr-r01/authoring.json');c=read(W/'review/candidate/report.json');b=read(W/'browser/report.json');perf=read(W/'performance.json');tiles=read(W/'review/tiles/inventory.json');visual=read(W/'visual-assessment.json');clearance=read(W/'clearance.json')
perf_baseline=read(W/'performance-baseline.json');assert perf_baseline['pass']
baseline=read(W/'review/baseline/report.json');assert len(baseline['views'])==8 and not baseline['errors'] and baseline['assets'] is None
assert len(c['views'])==8 and not c['errors'] and b['pass'] and perf['pass'];assert clearance['conflictsCount']==0;assert read(W/'default/report.json')['pass']
assert c['assets']=={name:v['sha256']for name,v in a['runtime']['files'].items()}
assert all(v['exposure']==.05 and v['position']==e['camera']['sourcePosition'] and not v['stats']['errors']for v in c['views'])
report={'version':'right-vr-r01','stage':'Reference-led candidate; not a certified exact VR replica','camera':e['camera'],'geometry':a['runtime']['lods'],'lighting':{'irradiance':a['irradiance'],'probes':a['probes'],'samples':a['samples'],'hdrEncoding':a['hdrEncoding']},'browser':b,'baselineCommit':'5bb26ba6083bd82feefc763a5c3bb1d4a8e5aba6','baselineCaptures':baseline,'captures':c,'performance':perf,'performanceBaseline':perf_baseline,'clearance':clearance,'visualAssessment':visual,'tiles':{'count':tiles['tileCount'],'parents64':tiles['parent64Count'],'accepted':False,'interpretation':'All covered cells inventoried; manual visual approval and independent full-edge error criterion are not established.'},'originalYacht':'629 hashes checked unchanged before publication; deployed verification recorded separately.'}
(D/'validation.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
style='body{font:16px/1.55 system-ui;background:#10171d;color:#e5ebef;max-width:1300px;margin:28px auto;padding:0 20px}a{color:#80d5ff}section{margin:32px 0}.views{display:grid;grid-template-columns:1fr 1fr;gap:14px}.private{grid-template-columns:1fr 1fr 1fr}figure{margin:0}img{width:100%;height:auto}figcaption,small{color:#bdcbd5}td,th{text-align:left;padding:8px;border-bottom:1px solid #456}table{border-collapse:collapse}@media(max-width:800px){.views,.private{grid-template-columns:1fr}}'
body='''<h1>Motor derecho · candidata VR R01</h1><p>Carcasas próximas, reductora, conexiones, escape, funda con pliegues y cierres, barandilla y extintor reconstruidos para el conjunto derecho. Los acabados tienen iluminación horneada y reflejos locales.</p><p><a href="../?room=machinery&amp;engine=right-vr-r01">Abrir ambos exteriores VR</a> · <a href="https://vrcloud.com/?pv=1667308298">Visita de referencia</a> · <a href="https://github.com/ageofresearch/ageofresearch.github.io/releases/tag/luz-right-engine-r01">Blender editable y fuentes</a></p><p>El motor izquierdo R13 conserva sus activos. La selección de cada lado cambia su exterior a la mecánica nominal R03 al activar el corte, y lo restaura al cerrarlo. La versión sin parámetro de candidata conserva los exteriores anteriores.</p>'''
body+=f'<p>{a["editableObjects"]} objetos editables. {a["runtime"]["lods"]["walk"]["triangles"]:,} triángulos en recorrido y {a["runtime"]["lods"]["detail"]["triangles"]:,} en detalle para el derecho. Atlas difuso HDR de 2048², dos reflejos de 1024×512. Texturas propias KTX2 y geometría meshopt.</p>'
body+=f'<p>Cámara fuente única: {e["camera"]["sourcePosition"]}. Ocho orientaciones con campos de visión documentados; exposición fija 0,05 y Three.js Neutral. Inventario privado de {tiles["tileCount"]} cuadros de 64/32 px. Una celda inventariada no equivale a una coincidencia aprobada.</p><p><a href="../assets/mechanics/right-vr-r01/component-inventory.json">Inventario por componente</a> · <a href="right-engine-r01/validation.json">Validación y mediciones</a> · <a href="right-engine-r01/authoring-archive.json">Hashes del archivo Blender</a></p>'
body+='<h2>Comprobaciones y límites</h2><p>Carga fallida y reintento, sustitución completa por lado, corte, cambio de lado, reinicio, registro central y retorno al cuarto comprobados. Las bancadas antiguas desaparecen con cada exterior para evitar superficies coplanares en el suelo.</p><ul>'+''.join('<li>'+html.escape(x)+'</li>'for x in visual['remainingDifferences'])+'</ul><p>Profundidades y caras ocultas inferidas. No se certifica una coincidencia exacta de todos los bordes ni la identidad del barco fotografiado. Los reflejos del contexto conservan la configuración del izquierdo; los nuevos reflejos locales corresponden al exterior derecho estático.</p>'
body+='<p>Rendimiento medido con Chromium/SwiftShader a 600 × 400. Son muestras cortas por software, no validación de 60/30 FPS en GPU física.</p><table><tr><th>Secuencia</th><th>p50 / p95</th><th>Dibujos / triángulos</th></tr>'
for s in [{**s,'name':'Anterior · '+s['name']}for s in perf_baseline['sequences']]+[{**s,'name':'Candidata · '+s['name']}for s in perf['sequences']]:body+=f'<tr><td>{html.escape(s["name"])}</td><td>{s["frameMs"]["p50"]:.1f} / {s["frameMs"]["p95"]:.1f} ms</td><td>{s["calls"]} / {s["triangles"]:,}</td></tr>'
body+='</table>'
added=b['withRightDetail']['estimatedMemory']['totalBytes']-b['beforeRight']['estimatedMemory']['totalBytes']
payload=sum(x['encodedBodySize']for x in perf['downloads']);transferred=sum(x['transferSize']for x in perf['downloads'])
body+=f'<p>Incremento estimado de recursos residentes durante la comprobación: {added/1048576:.1f} MiB, incluyendo la transición al detalle. Excluye cachés del controlador, programas y buffers de pantalla. Activos registrados en la prueba completa: {payload/1048576:.1f} MiB de cuerpos codificados; {transferred/1048576:.1f} MiB de transferencia informada por el navegador.</p><p>Los límites de un millón de triángulos y 120 llamadas se aplican al recorrido; el corte nominal se mide por separado. Las capturas originales de 1200 × 800 y la escena editable están disponibles en la entrega de GitHub.</p>'
private=body+'<p><a href="tiles/index.html">Comparación privada por cuadro</a></p>'
for pose in e['poses']:
 id=pose['id'];title=f'{id} · H {pose["h"]}° / V {pose["v"]}° · HFOV {pose["hfov"]}° / VFOV {pose["vfov"]:.3f}°'
 for folder in ['baseline','candidate']:Image.open(W/'review'/folder/(id+'.png')).save(D/(folder+'-'+id+'.webp'),quality=89)
 body+='<section><h2>'+title+'</h2><div class="views">'+''.join(f'<figure><img src="right-engine-r01/{f}-{id}.webp" loading="lazy" alt="{label}: {id}"><figcaption>{label}</figcaption></figure>'for f,label in [('baseline','Anterior · derecho nominal'),('candidate','Derecho VR R01 · WebGL')])+'</div></section>'
 private+='<section><h2>'+title+'</h2><div class="views private">'+''.join(f'<figure><img src="{src}" loading="lazy"><figcaption>{label}</figcaption></figure>'for src,label in [(f'../reference/{id}.png','VR original'),(f'baseline/{id}.png','Anterior'),(f'candidate/{id}.png','Candidata WebGL')])+'</div></section>'
body+='<p>Fotografías VR privadas, no publicadas ni usadas como texturas. Materiales generados en el proyecto. Dependencias: Three.js MIT, meshoptimizer MIT, Basis Universal Apache-2.0; autoría en Blender/Cycles y filtrado OIDN.</p>'
for file,content in [(P/'right-engine.html',body),(W/'review/index.html',private)]:file.write_text('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Motor derecho · VR R01</title><style>'+style+'</style>'+content+'</html>')
print('RIGHT REPORTS WRITTEN')
